"use client";

import "./spinner.css";
import { Loader2 } from "lucide-react";
import type React from "react";
import { cn } from "@/lib/cn";

import { spinnerVariants, type SpinnerVariants } from "./spinner.variants";

export type SpinnerProps = SpinnerVariants & React.ComponentProps<"svg">;

export const SpinnerRoot = ({
  className,
  size,
  variant,
  ...props
}: SpinnerProps) => {
  const slots = spinnerVariants({ size, variant });

  return (
    <Loader2
      role="status"
      aria-label="Loading"
      className={cn(slots.root(), className)}
      {...props}
    />
  );
};

export const Spinner = SpinnerRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const spinnerVariants = tv({
  slots: {
    root: "spinner",
  },
  variants: {
    size: {
      sm: { root: "spinner--sm" },
      md: { root: "spinner--md" },
      lg: { root: "spinner--lg" },
      xl: { root: "spinner--xl" },
    },
    variant: {
      default: { root: "" },
      muted: { root: "spinner--muted" },
      primary: { root: "spinner--primary" },
    },
  },
  defaultVariants: {
    size: "md",
    variant: "default",
  },
});

export type SpinnerVariants = VariantProps<typeof spinnerVariants>;

.spinner {
  @apply inline-block animate-spin text-current shrink-0;
}

.spinner--sm {
  @apply h-4 w-4;
}

.spinner--md {
  @apply h-6 w-6;
}

.spinner--lg {
  @apply h-8 w-8;
}

.spinner--xl {
  @apply h-12 w-12;
}

.spinner--muted {
  @apply text-muted-foreground;
}

.spinner--primary {
  @apply text-primary;
}

import { Spinner, SpinnerRoot } from "./spinner";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/spinner/content.md
 */
export const SpinnerContainer = {
  Root: SpinnerRoot,
};

export { Spinner, SpinnerRoot };

export type { SpinnerProps } from "./spinner";
export { type SpinnerVariants, spinnerVariants } from "./spinner.variants";
